else if (itens.length === 1 && Array.isArray(itens[0].data)) { brutas = itens[0].data; }
else { brutas = itens; }
const labels = brutas.map((l) => ({
  label_id: String(l.labelId || l.id || ''),
  nome: String(l.name || l.nome || ''),
  cor: l.color === undefined || l.color === null ? null : String(l.color),
})).filter((l) => l.label_id !== "");
// Zero label e resultado legitimo. Mandar assim mesmo: o SQL usa a lista
