const leads = $('Buscar leads a sincronizar').all().map((i) => i.json);

// A Evolution ja devolveu formato diferente do documentado neste projeto
// (o findChatByRemoteJid nem existe). Aceita as formas plausiveis.
const itens = $input.all().map((i) => i.json);
let chats = [];
if (itens.length === 1 && Array.isArray(itens[0].chats)) chats = itens[0].chats;
else if (itens.length === 1 && Array.isArray(itens[0].data)) chats = itens[0].data;
else if (itens.length === 1 && Array.isArray(itens[0])) chats = itens[0];
else chats = itens;

const porNumero = new Map();
for (const c of chats) {
  if (!c || typeof c !== 'object') continue;
  const jid = String(c.remoteJid || c.id || c.jid || '');
  const numero = jid.split('@')[0].replace(/\D/g, '');
  if (!numero) continue;
  const cru = Array.isArray(c.labels) ? c.labels : [];
  const labels = cru
    .map((l) => (typeof l === 'string' ? l : String((l && (l.labelId || l.id)) || '')))
    .filter((l) => l !== '');
  porNumero.set(numero, labels);
}

const saida = [];
for (const l of leads) {
  const numero = String(l.telefone || '').replace(/\D/g, '');
  if (!porNumero.has(numero)) continue; // sem dado = sem decisao
  saida.push({ json: { lead_id: l.id, telefone: l.telefone, labels: porNumero.get(numero) } });
}
return saida;
